  $LEGAL_e3368c4ab9276e${"id":"doc_immigration_rules_2051","title":"Immigration Rules, 2051 (1994)","originalTitle":null,"documentType":"regulation","yearBs":2051,"yearAd":1994,"totalPages":76,"nodes":[{"tier":1,"nodeType":"preamble","identifier":"Preamble","title":"Introductory matter","content":"अध्यागमन ननयमावली, २०५१\nन ेपाल र ाजपत्रमा प्रकाशित नमनत\n२०५१।0२।२३\nसंिोधन\n१. अध्यागमन (पहिलो संिोधन ) नन यमावली, २०५८ २०५८।0२।२२\n२. अध्यागमन (द ोस्रो संिोधन ) नन यामावली, २०५९ २०५९।0३।0३\n३. अध्यागमन (तेस्रो संिोधन ) नन यमावली, २०५९ २०५९।0६।२१\n४. अध्यागमन (चौथो संिोधन ) नन यमावली, २०६० २०६०।0४।१९\n५. अध्यागमन (पााँचौ संिोधन ) नन यमावली, २०६४ २०६५।0३।0२\nअध्यागमन ऐन , २०४९ को दफा १८ ले दद एको अनधकार प्रयोग गर ी न ेपाल सर कार ले\nद ेिायका नन यमिरू बन ाएको छ ।","children":[]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-1","title":null,"content":"प्रारशभिक","children":[{"tier":2,"nodeType":"rule","identifier":"1","title":"संशिप् त नाम र प्रारभिः (१) यी ननयमिरूको नाम “अध्यागमन ननयमावली, २०५१” र िेको छ।","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"यो ननयमावलीको ननयम २९ र ३९ न ेपाल सर कार ले न ेपाल र ाजपत्रमा सूचन ा\nप्रकािन गर ी तोके को नमनत द ेशि प्रार भि िुन े छ र अन्य नन यमिरू तुरु न्त प्रार भि\nिुन ेछन ्।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"2","title":"पररिाषाः हवषय वा प्रसङ्गले अको अथथ न लागेमा यो नन यमावलीमा,","content":"(क) “ऐन ” िन् नाले अध्यागमन ऐन , २०४९ सभझन ु पछथ ।\n(ि) “पयथटक” िन् नाले कशभतमा एक र ात वा चौहवस घण्टा न ेपालमा नबताउन े हवद ेिी\nसभझन ु पछथ ।\n नमनत २०६५।३।१६ को सूचन ाद्धार ा नमनत २०६५।0४।0१ द ेशि प्रार भि िुन े गर ी तोहकएको ।\n नमनत 2051।02।23 मा प्रकाशित न ेपाल र ाजपत्रको सूचन ाद्वार ा नन यम 39 आजैका नमनत द ेशि र नन यम 29 नमनत\n2051।03।17 तद्अन ुसार १ जुलाई 1994 द ेशि प्रार भि िुन े गर ी तोहकएको।\n(ग) “पररवार ” िन् नाले लोग्न े, स्वास्नी तथा आमा, बाबु आशित छोरा , छोर ी सभझन ु\nपछथ ।\n(घ) “पदयात्रा िेत्र” िन् नाले पद यात्रा गन थ अन ुमनत नलन ु पन े गर ी न ेपाल सर कारले\nतोके को ि ेत्र सभझन ु पछथ ।\n(ङ) “ननयोग ” िन् नाले हवद ेि शस्थत न ेपाली र ाजद ूतावास, न ेपाली मिावाशिज्य द ूतावास\nर न ेपाली वाशिज्य द ूतावास सभझन ु पछथ र सो िब्द ले स्थायी वा अस्थायी रूपमा\nन ेपाल सर कार को हवद ेिमा प्रनतनन नधत्व गन े सङ्गठन वा अनधकार ीलाई समेत\nजन ाउाँछ ।\n(च) “एजेन्सी” िन् नाले हवद ेिीिरू को आगमन , उपशस्थनत र प्रस्थानसभमको अवनधमा\nहवद ेिीलाई सेवा उपलब्ध गर ाउन े व्यशि वा न ेपाल सर कार को ईजाजत प्राप् त\nसंस्था तथा यात्रुिरु को आवागमन गर ाउन े संस्था सभझन ु पछथ ।\n(छ) “निसा वषथ” िन् नाले यस नन यमावलीको प्रयोजन को लानग कुन ै सालको जन वर ी १\nद ेशि निसेभबर ३१ सभमको अवनध सभझन ु पछथ ।","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-2","title":null,"content":"निसा सभबन्धी व्यवस्था\n३. निसा दद न े वा न दद न े न ेपाल सरकारको अनधकार ः (१) कुन ै हवद ेिीलाई निसा दद न े वा न दद न े\nसभपूिथ अनधकार न ेपाल सर कार मा नन हित र िन ेछ ।\n(२) न ेपाल सर कार ले कुन ै नमत्र र ाष्‍ट रका नागररकलाई पारस्पररकताको आधारमा निसा\nन नलई न ेपालनित्र प्रवेि गन थ दद न सक्न ेछ ।","children":[{"tier":2,"nodeType":"rule","identifier":"4","title":"कू टन ैनतक निसाः (१) न ेपाल सर कार ले हविेष आद ेि जार ी गरेको अवस्थामा बािेक कुन ै पनन","content":"मुलुकबाट कू टन ैनतक र ािद ान ी प्राप् त गर ी सभबशन्धत हवद ेिी कू टन ैनतक नन योगबाट कू टन ैनतक\nनिसाको नननमत्त नसफाररि गरी पठाएको व्यशि , न ेपाल सर कार बाट कू टन ैनतक सुहवधा प्रद ान गन थ\n पहिलो संिोधनद्वारा संिोनधत ।\nउपयुि ठिर् याएको व्यशि तथा त्यस्तो कू टन ैनतक र ािद ान ी प्राप् त व्यशिको पररवारका\nसदस्यलाई कू टन ैनतक निसा दद न न ेछ ।","children":[{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"कू टन ैनतक निसा न ेपालमा काम गरु न्जेलसभमको लानग पार स्परर कताको आधार मा\nएकै पटक वा पटक पटक भयाद थप गर ी दद न न ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"कू टन ैनतक निसाको लानग अन ुसूची–१ बमोशजमको ढााँचामा नन वेद न दद न ु पन ेछ ।\nतर हवद ेिी कू टन ैनतक नन योग वा सो कायथको लानग अनधकार प्राप् त ननकायबाट हववरि\nसहित अन ुर ोध वा नसफाररि िई आएमा अन ुसूची—१ बमोशजम नन वेद न दद न ु आवश्यक िुन ेछैन ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"5","title":"औपचाररक निसा (अहफनसयल निसा) (१) न ेपाल सर कार ले उपयुि ठिर् याएका व्यशि र","content":"नतन का परर वार तथा सभबशन्धत हवद ेिी कू टन ैनतक नन कायको नसफाररि मा द ेिायका हवद ेिी र\nनतन का परर वार लाई औपचारर क (अहफनसयल) निसा दद न न ेछ ।\n(क) न ेपालका लानग आवासीय वा गैर आवासीय कू टन ैनतक नन योग, वाशिज्य\nद ूतावासमा काम गन े प्रिासनन क, प्राहवनधक तथा गैर कू टन ैनतक कमथचार ी\nतथा बाह् य मुलुकबाट न ेपाल घुभन आउन े विालवाला न ेपाली अवैतनन क\nमिावाशिज्यद ूतिरू , वाशिज्यद ूतिरू र नतन का परर वार ,\n(ि) न ेपाल सर कार साँग िएको सभझौता बमोशजम न ेपालमा र िन े सल्लािकार\nहविेषज्ञिरू ,\n(ग) संयुि र ाष्‍ट र संघ वा त्यस अन्तगथतका संस्थािरू का न ेपाल शस्थत\nकायाथलयमा काम गन े कमथचार ीिरू र संयुि र ाष्‍ट र संघद्वार ा प्रद ान\nगररएको लेसेपेसे प्राप् त व्यशििरू ,\n(घ) न ेपाल शस्थत अन्तर ाथशष्‍ट रय संस्था वा ि ेत्रीय सङ्गठनिरूमा काम गने\nकमथचारीिरू ,\n(ङ) न ेपाल सर कार वा न ेपाल सर कार को स्वानमत्व िएको नन काय वा संयुि\nराष्‍ट र संघ वा ि ेत्रीय सङ्गठन वा सो अन्तगथतका अन्य ननकायद्वारा\nआयोशजत सिा सभमेलन , प्रशिि ि वा बैठकमा सििागी िुन आउन े\nव्यशििरु ।","children":[{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"औपचारर क निसाको लानग अन ुसूची–१ बमोशजमको ढााँचामा नन वेद न दद न ु पन ेछ।\nतर हवद ेिी कू टन ैनतक नन योग वा सो कायथको लानग अनधकार प्राप् त ननकायबाट हववरि\nसहित अन ुर ोध वा नसफाररि िई आएमा अन ुसूची–१ बमोशजमको नन वेद न दद न ु पन ेछैन ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"6","title":"पयथटक निसाः (१) न ेपाल भ्रमिमा आउन े हवद ेिी पयथटकलाई पयथटक निसा दद न न ेछ ।","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"पयथटक निसा एक निसा वषथमा बढीमा एकसय पचास ददनका लानग दद न न ेछ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"एक निसा वषथमा जार ी गरर एको निसामा तोहकएको अवनध पूर ा न गद ै प्रस्थान गरेको\nपयथटकले बााँकी अवनध अको निसा वषथमा जोिी उपयोग गन थ पाउन े छैन ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(४)","title":null,"content":"एक निसा वषथको अन्त्य नतर न ेपाल प्रवेि गर ी अको निसा वषथको पयथटक निसामा\nबस्न पाउन े अवनध पनन कुन ै हवद ेिीले उपिोग गन थ चािेमा सो सुहवधा नन जले उपयोग गन थ\nसक्न ेछ । तर त्यस्तो अवनधको द स्तूर को गिन ा िन े नन ज बसेको कू ल अवनधका आधार मा\nगरर न ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(५)","title":null,"content":"पयथटक निसाको लानग अन ुसूची–१ बमोशजमको ढााँचामा नन वेद न दद न ु पन ेछ ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"7","title":"अध्ययन निसाः (१) न ेपाल सर कार को स्वीकृ नत प्राप् त गर ी न ेपालको कुन ै शिि ि संस्थामा","content":"अध्ययन, अध्यापन वा अन ुसन्धान गन थ आउन े हवद ेिीिरू , नतनका पररवारलाई अध्ययन निसा\nदद न न े छ ।\n(२) न ेपाल सर कार बाट प्राप् त छात्रवृशत्त अन्तगथत वा न ेपाल सर कार बाट स्वीकृ त\nकायथक्रम अन्तगथत वा द ुई हवश् वहवद्यालय बीच िएको सभझौता अन्तगथत अध्ययन तथा\n पहिलो संिोधनद्वारा थप ।\n चौथो संिोधनद्वारा संिोनधत ।\n पााँचौ संिोधनद्वारा संिोनधत ।\nअन ुसन्धान गन थ आउन े वा द शि ि एशियाली ि ेत्रीय सियोग सङ्गठन (साक थ) का सदस्य\nरा ष्‍ट रिरु बाट अध्ययन गन थ आउन े हवद ेिी वा माध्यनमक तिसभमको अध्ययन गन थ आउन े हवद ेिी\nबािेक आफू ि ुिी अध्ययन तथा अन ुसन्धान गन थ चािन े अन्य हवद ेिीलाई न ेपालमा र िाँद ा एकै\nपटक वा मानसक द ामासािीमा वाहषथक न्यून तम तीन िजार अमेरर की िलर वा सो बर ाबर को\nन ेपाली मुद्रा र नन जका परर वार को िकमा वाहषथक न्यून तम द ुई िजार अमेरर की िलर वा सो\nबराबर को न ेपाली मुद्रा ि चथ गन थ सक्न े आनधकारर क स्रोत वा सो बराबर को वैद ेशिक मुद्राको\nसटिी रनसद वा सो ब र ाबर को न ेपाली मुद्रा स्थान ीय बैङ्कमा मौज्द ात र िेको कागजात पेि गरेको\nआधारमा मात्र अध्ययन निसा दद न न ेछ ।","children":[{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"अध्ययन निसा एक पटकमा एक वषथको लानग दद न न ेछ। सो िन्दा बढी अवनधको\nलानग दद न परेमा त्यस्ता व्यशि को अध्ययन तथा अन ुसन्धान प्रगनत हववर ि तथा हक्रयाकलाप\nलगायत अन्य आवश्यक कुर ािरू लाई समेत हवचार गर ी भयाद थप गन थ सहकन ेछ।\nतर अन ुसन्धान कताथ र अध्ययन कताथको िकमा यस्तो भयाद थप अन ुसन्धान अवनध वा\nअध्ययन र त िैशि क उपाधी अवनधसभमका लानग मात्र िुन ेछ ।\n(३क) उपननयम (३) मा जुन सुकै कुर ा लेशि एको िए तापनन प्राहवनधक हवषयमा\nअध्ययन गन ेिरु को िकमा सभबशन्धत हवषयमा िैशि क उपानध अवनधसभमको लानग एकै पटक\nअध्ययन निसा दद न सहकन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(४)","title":null,"content":"अध्ययन निसाको लानग सभबशन्धत मन्त्रालयको नसफाररि पेि गन ुथ पन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(५)","title":null,"content":"अध्ययन निसाको लानग अन ुसूची–२ बमोशजमको ढााँचामा नन वेद न दद न ु पन ेछ ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"8","title":"गैर पयथटक निसाः (१) द ेिायका हवद ेिी र नतन का परर वार का सद स्यिरू लाई गैर पयथटक निसा","content":"दद न न ेछ ।\n(क) हवद ेिी नमत्र र ाष्‍ट रका सर कार ी वा गैर सर कार ी संस्थाबाट ि चथ व्यिोन े\nगर ी न ेपाल सर कार को स्वीकृ नत प्राप् त सामाशजक वा आनथथक हवकास\nकायथमा संलग्न हवद ेिीिरू ,\n पााँचौ संिोधनद्वारा थप ।\n पहिलो संिोधनद्वारा संिोनधत ।\n(ि) न ेपाल शस्थत हवद ेिी नन योगद्वार ा संचानलत संस्थामा काम गन थको लानग\nपररा ष्‍ट र मन्त्रालयबाट नसफाररि प्राप् त हवद ेिीिरू ,\n(ग) हवद ेिी पत्रपनत्रका तथा समाचार सनमनतमा काम गन थको लानग सूचन ा\nतथा सञ् चार मन्त्रालयबाट नसफाररि प्राप् त हवद ेिी प्रनतनन नधिरू ,\n(घ) कू टन ैनतक वा औपचारर क निसा प्राप् त हवद ेिीको परर चार कको रू पमा\nकाम गनथ सभबशन्धत मन्त्रालयबाट नसफाररि प्राप् त हवद ेिीिरू ,\n(ङ) न ेपालनित्र कुन ै फमथ, कभपनी , संस्था, उद्योग वा व्यवसायमा पाररिनमक\nपाउन े गर ी काम गन थ न ेपाल सर कार बाट स्वीकृ त प्राप् त हवद ेिीिरू ,\n(च) न ेपालशस्थत कुन ै अन्तर ाथशष्‍ट रय िवाई संस्थामा काम गन थ सभबशन्धत\nमन्त्रालयबाट नसफाररि प्राप् त हवद ेिीिरू ,\n(छ) हवद ेिी सर कार ी नन काय वा हवद ेिी मुलुकको उद्योग वाशिज्य संघ वा\nच्याभवर अफ कमसथको नसफाररि मा तेस्रो मुलुकबाट न ेपाल आउन े\nहवद ेिी आयातकताथ,\n(ज) न ेपाली न ागरर कसाँग वैवाहिक सभबन्ध िई हववाि द ताथको प्रमािपत्र पेि\nगन े हवद ेिीिरू ।\n(ज१) न ेपाली मूलका हवद ेिी वा न ेपाली बाबु वा आमाको हवद ेिी र ािद ान ी\nवािक सन्तान न ेपालमा कुन ै न ातेद ार िेट्न आउन े िएमा वा न ेपाली\nन ागरर कसाँग वैवाहिक सभबन्ध िएका हवद ेिीका बाबु, आमा, द ाजु, िान ,\nदद द ी वा वहिन ी सभबशन्धत द ूतावासको न ाता ि ुलेको नसफाररि सहित\nनन जलाई िेट्न आउन े िएमा,\n पहिलो संिोधनद्वारा संिोनधत ।\n दोस्रो संिोधनद्वारा संिोनधत ।\n पााँचौ संिोधनद्वारा संिोनधत ।\nस्पष्‍ट टीकरिः यस िण्िको प्रयोजनका लानग “न ातेद ार ” िन् नाले बाबु वा\nआमापदिको तीन पुस्तानित्रको व्यशि लाई जन ाउन ेछ ।\n(झ) सर कार ी वा गैर सर कार ी स्तर मा सभपन् न सभझौता वा सिमनत अन ुसार\nसभबशन्धत मन्त्रालयको नसफाररि मा काम गन थ आएका हवद ेिीिरू ,\n(ञ) उद्योग वा व्यवसायको सभिाव्यता अध्ययन गनथ बढीमा ६ महिनासभमका\nलानग सभबशन्धत मन्त्रालयको नसफारर ि प्राप् त हवद ेिीिरु ,\nतर यस ि ण्ि बमोशजमका हवद ेिीिरु ले निसा नन वेद न फार ाम\nसाथ लगान ीको स्रोत ि ुलेको कागजात, लगानीकताथको योग्यता तथा\nअन ुिव सभबन्धी हववर ििरु समेत पेि गन ुथपन ेछ ।\n(ट) समूिगत रू पमा पयथटकिरू लाई न ेपाल भ्रमि गराउन सभबशन्धत\nमन्त्रालयको नसफाररि सहित आवेद न गन े हवद ेिीिरू को टोली न ेता,\n(ट१) समाज कल्याि परर षद् वा सभबशन्धत मन्त्रालयसाँग सभपन् न सभझौता\nअन ुसार गैर सर कार ी संस्थामा काम गन थ आउन े सभबशन्धत मन्त्रालयको\nनसफाररि प्राप् त हवद ेिीिरु ,\n(ठ) न ेपाल सर कार ले उपयुि ठिर् याएका हवद ेिीिरू ।","children":[{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"गैर पयथटक निसा एक पटकमा बढीमा एक वषथको लानग प्रद ान गरर न ेछ र\nआवश्यकता अन ुसार पुन ः भयाद थप गन थ सहकन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":".......","children":[]},{"tier":3,"nodeType":"clause","identifier":"(४)","title":null,"content":"गैर पयथटक निसा नलन को लानग अन ुसूची—२ बमोशजमको ढााँचामा नन वेद न दद न ु\nपनेछ ।\n पहिलो संिोधनद्वारा संिोनधत ।\n पहिलो संिोधनद्वारा थप ।\n पााँचौ संिोधनद्वारा शझहकएको ।\nतर उपननयम (१) को ि ण्ि (ज) बमोशजमका हवद ेिीिरू ले अन ुसूची—२क बमोशजमको\nढााँचामा नन वेद न दद न ु पन ेछ ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"9","title":"व्यावसाहयक निसाः (१) द ेिायका हवद ेिीिरू र नतन का परर वार लाई सभबशन्धत ननकायको","content":"नसफाररि मा व्यावसाहयक निसा दद न न ेछः–\n(क) न ेपालनित्र व्यापाररक वा औद्योनगक व्यवसायमा लगानी गने ईजाजत\nप्राप् त हवद ेिीिरू वा त्यस्ता व्यापारर क वा औद्योनगक संस्थाको अनधकृ त\nप्रनतनननध ।\n(ि) न ेपालबाट नन कासी व्यापार गन थ लगान ी गने नजाजत प्राप् त हवद ेिीिरू ।\n (ग) तेस्रो मुलुकबाट न ेपालमा आई न ेपालमा उत्पादद त मालसामान िरीद गरी\nनन कासी गन े वा नन कासीको लानग ि र ीद आद ेि दद न े हवद ेिीिरू ।","children":[{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"यस नन यमावलीमा अन्यथा व्यवस्था िएकोमा बािेक व्यावसाहयक निसा एक\nपटकमा बढीमा पााँच वषथका लानग प्रद ान गरर न ेछ र आवश्यकता अन ुसार यसको भयाद थप गन थ\nसहकन ेछ ।\n(२क) उपननयम (२) मा जुन सुकै कुर ा लेशि एको िएतापनन उपननयम (१) को िण्ि\n(ग) बमोशजमको हवद ेिीलाई एक पटकमा न ब्बे दद न सभम न ेपालमा बस्न पाउन े गर ी पााँच वषे\nबिु प्रवेिी व्यावसाहयक निसा दद न न ेछ ।\n(२ि) उपननयम (२क) बमोशजम न ेपालमा बस्न पाउन े गर ी दद न एको भयाद नित्र निसा\nवािकले व्यावसाहयक काम कार ोबार सभपन् न िुन न सके को कार ि र सभबद्ध प्रमाि समेत र ाि ी\nनन वेद न दद एमा नन जको कायथ द ि ताको आधार मा उपनन यम (२क) मा उल्लेि िए बमोशजम\nन ेपालमा बस्न पाउन े अवनधसभमको लानग निसा न वीकर ि गन थ सहकन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"व्यावसाहयक निसाको लानग अन ुसूची २ बमोशजमको ढााँचामा नन वेद न दद न ु पन ेछ।\n पहिलो संिोधनद्वारा थप ।\n दोस्रो संिोधनद्वारा थप ।\n१०. अन्तररम (राशन्जट) निसाः (१) न ेपालको हवमान स्थल िई कुन ै अको मुलुक जान े गर ी िवाई\nहटकटसहित रात नबताउन े गर ी न ेपालमा प्रवेि गरेका हवद ेिीलाई वा कुन ै कार िवि आकशस्मक\nरु पमा न ेपालको हवमान स्थलमा अवतर ि गरेको बायुयान मा यात्रा गरर र िेको हवद ेिीलाई एक\nददनका लानग अन्त रर म निसा दद न न ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"उपननयम (१) बमोशजमको निसाको लानग अन ुसूची – ३ बमोशजमको ढााँचामा\nनन वेद न दद न ु पन ेछ ।\n१०क .गैर आवासीय न ेपाली निसा (न न ् रेशजनियन्सल न ेपालीज निसा) : (१) हवद ेिमा बसोबास गन े\nन ेपाली मूलका हवद ेिीले न ेपालमा बसोबास गन थ वा व्यापार व्यवसाय वा कुन ै हवषयमा अध्ययन\nअध्यापन वा अन ुसन्धान गन थ चािेमा नन ज र नन जको परर वार लाई गैर आवासीय न ेपाली निसा दद न\nसहकन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"उपननयम (१) बमोशजमको निसाको लानग अन ुसूची–३क. बमोशजमको ढााँचामा\nहवद ेिशस्थत न ेपाली नन योग माफथत वा हविागमा सोझै नन वेद न दद न सहकन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"उपननयम (१) बमोशजमको निसा एकपटकमा बढीमा दिवषथसभमको लानग प्रदान\nगन थ सहकन ेछ र आवश्यकता अन ुसार यसको भयाद थप गन थ सहकन ेछ ।","children":[]},{"tier":3,"nodeType":"clause","identifier":"(४)","title":null,"content":"गैर आवासीय न ेपाली निसाको ढााँचा अन ुसूची—३ि . बमोशजमको िुन ेछ ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"11","title":"आवासीय (रेशजिेशन्सयल) निसाः (१) न ेपालमा जीवन हवताउन चािन े द ेिायका हवद ेिीिरु र","content":"नतन का परर वार लाई आवासीय निसा दद न न ेछ ।\n(क) अन्तराथशष्‍ट रय ख्यानत प्राप् त व्यशि,\n(ि) न ेपालको आनथथक, सामाशजक र सांस्कृ नतक समुन् ननतमा हविेष योगद ान\nपुर् याउन सक्न े व्यशि ,\n (ग) =......,\n दो स्रो संिोधन द्वारा थप।\n पााँचौ संिोधनद्वारा संिोनधत ।\n दोस्रो संिोधनद्वारा शझहकएको ।\n(घ) न ेपालको औद्योनगक व्यवसायमा कशभतमा एकलाि अमेरर की िलर वा\nसो बर ाबर को परर वत्र्य हवद ेिी मुद्रा एकै पटक लगान ी गन े व्यशि ,\n(ङ) न ेपालमा कुन ै व्यवसाय न गर ी जीवन यापन गन थ चािन े हवद ेिी ।\n(२) उपननयम (१) को ि ण्ि (घ) मा उल्लेि िएका हवद ेिी बािेक अन्य ि ण्िमा\nउल्लेि िएका हवद ेिीलाई आवासीय निसा नसफाररि गन े नन योगले पर र ाष्‍ट र मन्त्रालय माफ थ त\nत्यस्तो हवद ेिीले िरेको नन वेद न सहित हविागमा पठाउन ु पन ेछ ।\n(३) उपननयम (१) को िण्ि (ङ) को आधारमा आवासीय निसा प्राप् त गनथ चािन े\nहवद ेिीले एकमुष्ट वाहषथक बीस िजार अमेरर की िलर वा सो बराबर को परर वत्र्य हवद ेिी मुद्रा\nन ेपालमा ि चथ गन े स्रोत प्रमाशित िुन े कागजात र न वीकर ि गन थ चािन े हवद ेिीले सो कागजात\nसहित एकमुष्ट वा पटक पटक उि र कम ि चथ गरेको पुशष्‍ट ट िुन े प्रमाि पेि गन ुथ पन ेछ ।","children":[{"tier":