ष्‍ट र मन्त्रालय ।\nलाग्न े निसा ि ुल्क नलई ⁄ नन :ि ुल्क मेर ो निसाको भयाद थप गर ी दद न ु िुन अन र ोध गरेको छु ।\nमेर ो हववर ि नन भन अन ुसार छ ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"1","title":"नाम , थरः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"2","title":"रा शष्‍ट रयताः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"3","title":"जन्म स्थानः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"4","title":"जन्म नमनतः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"5","title":"स्थायी ठेगान ाः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"6","title":"न ेपालको अस्थायी ठेगान ाः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"व्यवसायः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"(क) रािदानी नभबरः (ि) जारी नमनतः","content":"(ग) बिाल नमनतः\n(घ) आफ्नो न ाममा अन्य द ेिको र ािद ान ी िए द ेिको न ाम र र ािद ान ी न भबर ः\nफोटो","children":[]},{"tier":2,"nodeType":"rule","identifier":"9","title":"(क) प्रवेि निसा जार ी गरर एको स्थान ः (ि) नमनतः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"10","title":"(क) अशन्तम निसा बिाल र िन े नमनतः (ि) निसा शस्टकर नभबरः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"11","title":"यो वषथ न ेपाल वसेको कू ल अवनधः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"12","title":"माग गरेको निसाको हकनसमः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"13","title":"निसा माग गरेको अवनधः नमनत ............... द ेशि ............ सभम ........... दद न","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"14","title":"एक प्रवेिी ⁄ द ुई प्रवेिी ⁄ विु प्रवेिी निसा माग गरेको िए उल्लेि गन ेः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"15","title":"निसा भयाद थप गन ुथ पन े कार िः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"16","title":"न ेपाल बसाईका लानग छुट्यान एको र कमः (हवद ेिी मुद्रामा)","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"17","title":"न ेपालबाट प्रस्थान गने नमनतः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"18","title":"प्रस्थान स्थलः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"19","title":"जान े मुलुकः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"20","title":"फकथन े िवाई ⁄ बस ⁄ हटकट छ छैन ः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"21","title":"संलग्न कागजातिरू ः","content":"(क) .....................\n(ि) .....................\n(ग) .....................\nनमनतः\n........................\nनन वेद कको िस्ताि र\nअन ुसूची-९\n(नन यम २९ साँग सभबशन्धत)\nनिसा द स्तूर","children":[]},{"tier":2,"nodeType":"rule","identifier":"1","title":"नन योग वा प्रवेिस्थल शस्थत कायाथलयले पयथटक निसा जार ी गद ाथ लाग्न े द स्तुर ः","content":"(क) पन्र दद न को बिुप्रवेिी सुहवधा सहितको निसाका लानग तीस अमेरर की िलर वा सो\nबराबरको अन्य परर वत्र्य हवद ेिी मुद्रा ।\n(ि) तीस दद न को बिुप्रवेिी सुहवधा सहितको निसाका लानग पचास अमेरर की िलर वा सो\nबर ाबर को अन्य परर वत्र्य हवद ेिी मुद्रा ।\n(ग) न ब् बे दद न को बिुप्रवेिी सुहवधा सहितको निसाका लानग एक सय पच् चीस अमेरर की िलर\nवा सो बर ाबर को परर वत्र्य हवद ेिी मुद्रा ।\n(घ) ि ण्ि (क) र (ि ) मा जुन सुकै कुर ा लेशि एको िए तापनन द शि ि एशियाली िेत्रीय\nसियोग सङ्गठन (साक थ ) का सदस्य राष्‍ट रका रािदानी बािकलाई तीस ददनसभमको\nअवनधका लानग निसा द स्तूर लाग्न े छैन ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"2","title":"पयथटक निसाको भयाद थप वा नन यनमत गद ाथ लाग्न े द स्तुरः","content":"(क) भयाद थप गनथ प्रनत ददनको तीन अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(ि) भयाद थप अवनधका लानग मात्र मान्य िुन े गर ी बिुप्रवेिी सुहवधा माग गरेमा ि ण्ि (क)\nबमोशजमको द स्तूर मा थप पच् चीस अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(ग) पयथटक निसाको भयाद थप न गर ी बसेका हवद ेिीको निसा नन यनमत गन ुथ परेमा यस\nनन यमावली बमोशजम निसा भयाद थप गद ाथ लाग्न े साधार ि द स्तूर मा प्रनत ददनको पााँच\nअमेरर की िलर का द र ले िुन आउन े र कम बर ाबर को न ेपाली मुद्रा थप द स्तूर लाग्न े,\n नमनत २०७६।३।३० को र ाजपत्रमा प्रकाशित सूचन ाद्वार ा संिोनधत ।\n(घ) पयथटक निसामा बस्न पाउन े अवनध एक सय पचास दद न िन्द ा बहढ अवनध निसाको भयाद\nथप न गर ाई बसेका हवद ेिीको िकमा ि ण्ि (ग) मा उशल्लशि त द स्तूर र ऐनको दफा\n१० को उपदफा (४) बमोशजम िुन सक्न े जरर वान ा समेत थप लाग्न े,\n(ङ) िण्ि (क) मा जुन सुकै लेशि एको िए तापनन पयथटक निसाको भयाद थप गन े प्रयोजनका\nलानग निसा द स्तूरको गिना गदाथ पन्र ददन िन्दा कम अवनधको िए पन्र ददनको र सो\nिन्दा बढी अवनधको िए िण्ि (क) बमोशजमको द स्तूर लाग्न े ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"3","title":"अध्ययन निसा जारी गदाथ वा भयाद थप गद ाथ लाग्न े द स्तुर ः","content":"(क) प्रवेिको समयमा तीस दद न को अध्ययन निसा जार ी गन ुथ परेमा तीस अमेरर की िलर वा\nसो बराबरको अन्य पररबत्र्य हवद ेिी मुद्रा,\n(ि) अध्ययन निसा जार ी गद ाथ वा भयाद थप गद ाथ िैशि क उपानध प्राप् त िुन े गर ी (Degree\nprogramme) अध्ययनरत हवद्याथी र नतनका आशित पररवारलाई प्रनत महिना तीस\nअमेरर की िलर बर ाबर को न ेपाली मुद्रा, िैशि क उपानध प्राप् त न िुन े गर ी (Non-Degree\nProgramme) अध्ययनरत हवद्याथी र नतनका आशित पररवारलाई प्रनत महिना पचित्तर\nअमेरर की िलर बर ाबर को न ेपाली मुद्रा,\n(ग) बंगलाद ेिबाट अध्ययन गन थ आउन े हवद्याथी र नतनका आशित पररवारलाई\nपार स्परर कताको आधार मा बिुप्रवेिी अध्ययन निसा जार ी गद ाथ वाहषथक पन्र अमेरर की\nिलर बर ाबर को न ेपाली मुद्रा,\n(घ) माशल्द भ्सबाट अध्ययन गन थ आउन े हवद्याथी र नतनका आशित पररवा रलाई\nपार स्परर कताको आधार मा बिुप्रवेिी अध्ययन निसा जार ी गद ाथ वाहषथक पच्चीस अमेरर की\nिलर बर ाबर को न ेपाली मुद्रा,\n(ङ) िुटान बाट अध्ययन गन थ आउन े हवद्याथी र नतन का आशित परर वार लाई बिुप्रवेिी अध्ययन\nनिसा जार ी गद ाथ मानसक पन्र अमेरर की िलर बर ाबर को न ेपाली मुद्रा,\n(च) ि ण्ि (ि ) मा जुन सुकै कुर ा लेशि एको िए तापनन िीलंका र पाहकस्तान बाट अध्ययन\nगन थ आउन े हवद्याथीलाई पारस्पररकताका आधारमा अध्ययन निसा जारी गदाथ निसा द स्तूर\nलाग्न े छैन ,\nतर त्यस्ता हवद्याथीका परर वार लाई अध्ययन निसा जार ी गद ा निसा ि ुल्क बापत\nमानसक दि अ मेरर की िलर बर ाबर को न ेपाली मुद्रा लाग्न ेछ ।\n(छ) न ेपालशस्थत हवश् वहवद्यालयिरु र हवद ेिी हवश् वहवद्यालयिरु बीच शििक आदान –प्रदान\nकायथक्रम अन्तगथत न ेपाल आई नन ःि ुल्क अध्ययन निसा प्राप् त गने िनी ननिथय िएका\nहवद ेिीका आशित परर वार लाई अध्ययन निसा जार ी गद ाथ मानसक पन्र अमेरर की िलर\nबर ाबर को न ेपाली मुद्रा,\n(ज) अध्यापन तथा अन ुसन्धान गन थ आउन े अन्य हवद ेिी र नतन का आिीत परर वार लाई\nमानसक पचास अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"4","title":"गैर पयथटक निसा जारी गद ाथ वा भयाद थप गद ाथ लाग्न े द स्तुरः","content":"(क) प्रवेिको समयमा तीस दद न को गैर पयथटक निसा जार ी गन ुथ परेमा तीस अमेरर की िलर\nवा सो बराबरका अन्य पररवत्र्य हवद ेिी मुद्रा ।\n(ि) न ेपाली मूलका हवद ेिी र न ेपाली बाबु वा आमाका हवद ेिी र ािद ान ी बािक सन्तान लाई\nप्रनत महिन ा द ि अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(ग) पत्रकार र नतनका आशित प ररवारलाई प्रनत महिना पन्र अमेरर की िलर बर ाबर को\nन ेपाली मुद्रा ।\n(घ) न ेपाल सर कार को कायाथलय वा आयोजन ामा प्रत्यि रु पमा संलग्न िई कायथर त िुन े\nहवद ेिी र नतन का आशित परर वार लाई प्रनत महिन ा तीस अमेरर की िलर बर ाबर को न ेपाली\nमुद्रा ।\n(ङ) न ेपाली न ागरर कसाँग हववाि गन े हवद ेिीलाई प्रनत महिन ा पन्र अमेरर की िलर बर ाबर को\nन ेपाली मुद्रा ।\n(च) न ेपाली न ागरर कसाँग वैवाहिक सभबन्ध िएका हवद ेिीका बाबु, आमा, द ाजु, िान , दददी वा\nबहिन ी नन जलाई िेट्न आउन े िएमा वा न ातेद ार िेट्न े प्रयोजन का लानग आउन े अन्य\nहवद ेिीलाई प्रनत महिन ा पच्चीस अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(छ) न ेपाल सर कार वा न ेपाल सर कार को पूिथ स्वानमत्व र िेको संस्थासाँग ठेक्का पिामा काम\nगन थ िम स्वीकृ नत प्राप् त वा सन ् १९८९ िन्द ा अशघद ेशि न ेपालमा कुन ै कार ोवार गरर\nबसेका शचन ीया न ागरर कलाई प्रनत महिन ा बीस अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(ज) द ातृर ाष्‍ट र र न ेपाल सर कार बीच सभझौता िई द ातृर ाष्‍ट रको प्रत्यि लगानीमा सञ् चानलत\nगैर सर कार ी संस्थामा कायथर त हवद ेिी र नतन का आशित परर वार लाई प्रनत महिन ा पचास\nअमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(झ) अन्य हवद ेिीिरु लाई प्रनत महिन ा पचित्तर अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।\n(ञ) ि ण्ि (ङ) मा जुन सुकै कुर ा लेशि एको िए तापनन अध्यागमन नन यमावली, २०५१ लागु\nिुन ु िन्द ा अशघ हवद ेिी सभबन्धी नन यमावली, २०३२ बमोशजम नन ि ुल्क निसा प्राप् त\nगरर सके का न ेपाली पुरु ष न ागरर कसाँग वैवाहिक सभबन्ध िएका हवद ेिी महिलालाई\nवैवाहिक सभबन्ध कायम र िेसभम निसा द स्तूर न लाग्न े ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"5","title":"व्यावसाहयक निसा जारी गदाथ वा भयाद थप गद ाथ लाग्न े द स्तुर ः","content":"(क) एक कर ोि रु पैयााँ िन्द ा बढी व्यशिगत लगान ी गन े हवद ेिी र नतन का आशित परर वार\nवा संस्थाका अनधकृ त प्रनतनन नधलाई द ेिायको अवनधको लानग बिुप्रवेिी व्यावसाहयक\nनिसा जारी गदाथ द ेिाय बमोशजमको द स्तूर लाग्न ेछः–","children":[{"tier":3,"nodeType":"clause","identifier":"(१)","title":null,"content":"एक वषथिन्द ा कम अवनधको निसा जार ी गद ाथ मानसक बीस अमेरर की िलर\nबर ाबर को न ेपाली मुद्रा,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"वाहषथक रु पमा निसा जार ी गद ाथ द ुई सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा, र","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"पााँच वषथको निसा जारी गद ाथ पााँच सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा।\n(ि) एक कर ोि रु पैयााँ र सो िन्द ा कम व्यशिगत लगानी गने हवद ेिी र नतनका आशित\nपरर वार वा संस्थाका अनधकृ त प्रनतनन नधलाई द ेिायको अवनधको लानग बिुप्रवेिी\nव्यावसाहयक निसा जार ी गद ाथ द ेिाय बमोशजमको द स्तूर लाग्न ेः–","children":[]},{"tier":3,"nodeType":"clause","identifier":"(१)","title":null,"content":"एक वषथिन्दा कम अवनधको निसा जार ी गद ाथ मानसक पैंतीस अमेरर की िलर\nबर ाबर को न ेपाली मुद्रा,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(२)","title":null,"content":"वाहषथक रु पमा निसा जार ी गद ाथ चार सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा र ,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(३)","title":null,"content":"पााँच वषथको निसा जार ी गद ाथ एक िजार अमेरर की िलर बर ाबर को न ेपाली मुद्रा।\n(ग) न ेपालमा उत्पाददत मालसामान िररद गरी ननकासी गने वा ननकासीको लानग िररद\nआद ेि दद न े हवद ेिीलाई िण्ि (क) बमोशजमको निसा द स्तूर लाग्न े।\n(घ) ि ण्ि (क) र (ि ) मा जुन सुकै कुर ा लेशि एको िए तापनन द ि कर ोि रु पैयााँ वा सो\nिन्दा बढी व्यशिगत लगान ी गन े हवद ेिी र नतन का आशित परर वार वा संस्थाका\nअनधकृ त प्रनतनन नधलाई बिुप्रवेिी व्यवसाहयक निसा जारी गदाथ निसा द स्तूर न लाग्न े ।\n(ङ) प्रहवनध िस्तान्तर ि प्रयोजन का लानग आउन े हविेषज्ञ र नन जको आशित परर वार लाई िण्ि\n(ि ) मा उल्लेि िए बमोशजम निसा द स्तूर लाग्न े ।","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"6","title":"अन्तररम निसा जारी गद ाथ लाग्न े द स्तुर ः अन्तरर म निसा जार ी गद ाथ पााँच अमेरर की िलर वा सो","content":"बर ाबर को परर वत्र्य हवद ेिी मुद्रा ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"गैर आवासीय न ेपाली निसा जार ी गद ाथ वा भयाद थप गद ाथ लाग्न े द स्तुरः बिुप्रवेिी निसाका लानग","content":"वाहषथक एक सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा र अध्ययन गन थ आउन े हवद्याथीका\nिकमा वाहषथक पच्चीस अमेरर की िलर बर ाबर को न ेपाली मुद्रा ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"बिुप्रवेिी सुहवधा सहित आवासीय निसा जार ी गद ाथ वा न वीकर ि गद ाथ लाग्न े द स्तुर ः","content":"(क) पहिलो पटक पााँच सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा र न वीकर ि गद ाथ वाहषथक\nद ुई सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा,\n(ि) ननयमावलीको ननयम ११ को उपननयम (१) को ि ण्ि (ङ) बमोशजमको हवद ेिीका\nलानग पहिलो पटक सात सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा र न वीकर ि गद ाथ\nवाहषथक एक िजार द ुई सय अमेरर की िलर बर ाबर को न ेपाली मुद्रा,\n(ग) ि ण्ि (ि ) मा जुन सुकै कुर ा लेशि एको िए तापनन अध्यागमन नन यमावली, २०५१ को\nपहिलो संिोधन , (२०५८।२।२२) लागु िुन ु पूवथ सो नन यमावलीको ननयम ११ को\nउपननयम (१) को िण्ि (ङ) बमोशजम आवासीय निसा प्रा प् त गर ी न ेपालमा बसी\nआएका हवद ेिीलाई न वीकर ि द स्तूर बापत वाहषथक एक सय अमेरर की िलर बर ाबर को\nन ेपाली मुद्रा ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"9","title":"व्यावसाहयक, अध्ययन र गैर पयथटक निसाको भयाद थप न गर ी बसेका हवद ेिीको निसा ननयनमत","content":"गद ाथ लाग्न े द स्तुर ः\n(क) व्यावसाहयक, अध्ययन र गैर पयथटक निसाको नसफाररि हविागमा द ताथ िएको नमनतद ेशि\nमात्र नसफाररि गररए बमोशजमको निसा प्राप् त िुन े िएकाले समयमै निसाको भयाद थप\nन गर ी बसेका हवद ेिीका िकमा सभबशन्धत नन कायबाट पुन ः सोिी निसाको नसफाररि\nप्राप् त िएमा भयाद थप न गर ी बसेको अवनधका िकमा पहिले जुन निसामा बसेको िो सो\nनिसाबापत यस नन यमावली बमोशजम लाग्न े द स्तूर मा सत प्रनतित थप द स्तूर लाग्न े,\nतर साहवक निसा पयथटक नि सा िएमा एक सय पचास ददनको अवनध नित्रको\nिए क्रम संख्या २ बमोशजम पयथटक निसाको भयाद थप वा नन यनमत गद ाथ लाग्न े द स्तूर\nसरिको द स्तूर लाग्न ेछ ।\n(ि) ि ण्ि (क) बमोशजम पुन ः नसफाररि प्राप् त निएमा एक सय पचास ददनको अवनधनित्रको\nिए क्रम संख्या २ अन ुसार पयथटक निसाको भयाद थप वा नन यनमत गद ाथ लाग्न े द स्तूर\nसरिको द स्तूर र सो अवनध िन्दा बढी िए ऐनको दफा १० को उपदफा (४)\nबमोशजम जरर वान ा समेत लाग्न े ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"10","title":"पयथटक निसा बािेक अन्य निसाको मान्य अवनधसभम मात्र कायम र िन े गरी एक प्रवेिी र","content":"बिुप्रवेिी सुहवधा नलन ु परेमा लाग्न े द स्तुरः एक प्रवेिीका लानग बीस र बिुप्रवेिीका लानग साठी\nअमेरर की िलर बर ाबर को न ेपाली मुद्रा ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"11","title":"अन्य द स्तुर ः","content":"(क) प्रवेिस्थलबाट निसा न नलई प्रवेि गन े हवद ेिीलाई पयथटक निसा जार ी गन ुथ परेमा यस\nनन यमावली बमोशजम लाग्न े द स्तूर मा पचास प्रनतित थप गर ी सो बर ाबर को न ेपाली मुद्रा\nलाग्न ेछ ।\n(ि) यात्रा अन ुमनतपत्र जार ी गद ाथ तीस अमेरर की िलर बर ाबर को न ेपाली मुद्रा लाग्न े ।\n(ग) आगमन वा प्रस्थान प्रमाशित गद ाथ वा निसा स्थान ान्तर ि गन ुथ परेमा द ुई अमेरर की िलर\nबर ाबर को न ेपाली मुद्रा लाग्न े ।\n(घ) ि ण्ि (क) मा जेसुकै लेशि एको िए तापनन यस नन यमावली बमोशजम प्रवेि निसा द स्तूर\nन लाग्न े व्यवस्था िएका हवद ेिी (द ि वषथ मुनन का बािेक) प्रवेि स्थलबाट निसा ननलई\nप्रवेि गरेमा नबिागबाट प्रवेि निसा जार ी गद ाथ क्रम संख्या १ को िण्ि (क), (ि) वा\n(ग) बमोशजमको द स्तूर बर ाबर को न ेपाली मुद्रा र यस नन यमावली वा न ेपाल सर कार ले\nनिसा द स्तूर न लाग्न े व्यवस्था गरेका हवद ेिीले निसाको भयाद थप न गर ी बसेमा निसा\nनन यनमत गद ाथ सोह्र वषथ मुनन का हवद ेिीका िकमा नन जका अनििावक र सोह्र वषथ मानथका\nहवद ेिीका िकमा र ािद ान ी बािकलाई ऐन को द फा १० को उपदफा (४) अन ुसार\nजरर वान ा िुन सक्न े।","children":[]},{"tier":2,"nodeType":"rule","identifier":"12","title":"निसा द स्तूरको गिनाः पयथटक निसा बािेक अन्य निसाको द स्तूर गिना गने प्रयोजनका लानग","content":"अवनध गिना गदाथ पन्र ददन िन्दा कम अवनधको िए पन्र ददनसभमको र पन्र ददनिन्दा बढी\nर एक महिना िन्दा कम अवनधको िए एक महिनाको निसा द स्तूर लाग्न े गर ी द स्तूर को गिना\nगरर न े।","children":[]},{"tier":2,"nodeType":"rule","identifier":"13","title":"आवासीय निसाको नवीकरि नगरी बसेका हवद ेिीलाई लाग्न े द स्तुर ः आवासीय निसा नवीकरि","content":"न गर ी बसेका हवद ेिीको निसा न वीकर ि गद ाथ नन यम बमोशजम लाग्न े द स्तूर मा मानसक तीस\nअमेरर की िलर बर ाबर को न ेपाली मुद्रा थप द स्तूर लाग्न े।","children":[]},{"tier":2,"nodeType":"rule","identifier":"14","title":"गैर आवासीय न ेपाली निसाको भयाद थप न गर ी बसेका हवद ेिीलाई लाग्न े द स्तुर ः गैर आवासीय","content":"न ेपाली निसाको भयाद थप न गर ी बसेका हवद ेिीको भयाद थप गन ुथ परेमा यस नन यमावली\nबमोशजम लाग्न े द स्तूर मा मानसक द ि अमेरर की िलर बर ाबर को न ेपाली मुद्रा थप द स्तूर लाग्न े।\nअन ुसूची १०\n(ननयम ३२ साँग सभबशन्धत)\nपदयात्रा अन ुमनतका लानग नन वेद न फार ाम\nिी मिानन द ेिकज्यू,\nअध्यागमन हविाग ।\nमलाई न ेपालको नन भन स्थान मा पद यात्रा गन े ईच्छा िएकोले नन भन हववर ि ि ुलाई नन वेद न\nदद एको छु । उल्लेशि त ि ेत्रमा पद यात्रा गन थ अन ुमनत दद न एमा प्रचनलत कान ून तथा अध्यागमन\nननयमावली , २०५१ को पररनधनित्र र िी पद यात्रा गन े व्यिोर ा अन ुर ोध गद थछु ।\nतपनसल","children":[]},{"tier":2,"nodeType":"rule","identifier":"1","title":"पयथटकको हववरि","content":"नाम थरः रा शष्‍ट रयताः\nजन्म नमनतः स्थायी ठेगान ाः\nव्यवसायः अस्थायी ठेगान ाः\nरािदानी नभबरः र ािद ान ी जार ी गरेको नमनतः\nप्रवेि निसा जार ी गरर एको स्थान ः नमनतः\nनिसा बिाल र िन े नमनतः","children":[]},{"tier":2,"nodeType":"rule","identifier":"2","title":"पदयात्राको उद्देश्यः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"3","title":"पदयात्रा गने िेत्रः","content":"फोटो","children":[]},{"tier":2,"nodeType":"rule","identifier":"4","title":"पदयात्रा गने बाटोः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"5","title":"पदयात्राको अवनधः नमनत .................. द ेशि ........... सभम ..... दद न","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"6","title":"पद यात्रा ि ुरु गन े स्थान ः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"पदयात्रा समाप् त िुन े स्थान ः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"पद यात्राको लानग अन ुमानन त िचथः (परर वत्र्य हवद ेिी मुद्रामा उल्लेि गन े)","content":"नमनतः\n........................\nनन वेद कको िस्ताि र\nद्रष्टव्यः उल्लेशि त स्थान मा जान े बाटोको न क्सा माग िएमा यसै साथ बुझाउन ु पन ेछ ।\nअन ुसूची–१०क.\n(ननयम ३२ साँग सभबशन्धत)\nएजेन्सी माफथत पद यात्रा अन ुमनत नन वेद न फाराम\nहवषयः– पद यात्रा अन ुमनत उपलब्ध गर ान दद न े ।\nिी मिानन द ेिकज्यू,\nअध्यागमन हविाग, काठमािौं ।\nिाम्रो नजाजत प्राप् त र ेहकङ्ग एजेन्सी माफथत नन भन पयथटकिरू ले पद यात्रा गन थ जान न च्छा\nगरेकोले नन जिरू लाई पद यात्रा अन ुमनत उपलब्ध गर ाई दद न ु िुन अन ुर ोध गद थछु । अन ुमनत द स्तूर बापत\nर कम रू . ........ संलग्न छ ।\nपदयात्रा गराए बापत सेवा ि ुल्क जभमा र कम ....... (परर वत्र्य हवद ेिी मुद्रा उल्लेि गन े)\nनलएका ⁄ नलन ेछौं । ऐन तथा नन यमावलीले नन द ेिन गरेका सभपूिथ ितथिरू को पालन ा गर ी नन धाथरर त ि ेत्र\nर बाटोमा पद यात्रा गर ाउन ेछौं ।\nपयथटकिरू को हववर ि नन भन ान ुसार छ\nनस.न ं. नाम ,\nथर\nराशष्‍ट रयता रािदानी\nन ं. र\nबिाल\nर िन े\nनमनत\nप्रवेि\nनिसा\nजारी\nगरेको\nस्थल र\nनमनत\nआगमन\nस्थल र\nनमनत\nनिसा\nबिाल\nर िन े\nनमनत\nपदयात्रामा\nजान े ि ेत्र र\nजान े अवनध\n.........\nद ेशि .......\nसभम\nददन.....\nपदयात्रा\nि ुरु र\nसमाप् त\nिुन े\nस्थान\nपदयात्राको\nमागथ\n१.\n२.\n३.\nबोधाथथः\nिी कर कायाथलय, ................... शजल्ला । नजाजत प्राप् त एजेन्सीको अनधकार\nिी न ेपाल र ाष्‍ट र बैङ्क । प्राप् त अनधकारीको\nहवद ेिी हवनन मय हविाग । नाम , थर\nिी पयथटन हविाग, नत्रपुरेश् वर , काठमािौं । दस्तितः\nनमनतः\nअन ुसूची ११\n(ननयम ३३ साँग सभबशन्धत)\nन ेपाल सरकार\nगृि मन्त्रालय\nअध्यागमन हविाग\nपद यात्रा अन ुमनतपत्र\nअध्यागमन ननयमावली , २०५१ को ननयम ३३ बमोशजम ननभन पयथटकलाई ननभन िेत्र (उि\nिे त्रमा पन े नन षेनधत ईलाका बािेक) मा नमनत ......................... द ेशि .................. सभम पद यात्रा\nगन थ अन ुमनत प्रद ान गरर एको छ ।","children":[]},{"tier":2,"nodeType":"rule","identifier":"1","title":"नाम थरः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"2","title":"रा शष्‍ट रयताः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"3","title":"स्थायी ठेगान ाः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"4","title":"न ेपालको अस्थायी ठेगान ाः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"5","title":"रािदानी नभबरः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"6","title":"न ेपाली निसाको भयाद ः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"पदयात्रा गन थ अन ुमनत दद न एको ि ेत्रः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"पदयात्राको लानग ननधाथररत बाटोः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"9","title":"पदयात्रा ि ुरु िुन े स्थान ः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"10","title":"पदयात्रा समाप् त िुन े स्थान ः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"11","title":"र ेहकङ्ग एजेन्सी माफथत पद यात्रा गन े िए एजेन्सीको न ामः","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"12","title":"पद यात्रा अन ुमनत न भबर ः","content":"नमनतः .....................\nअध्यागमन अनधकृ त\nकोि नभबरः\nद्रष्टव्यः (१) नन धाथर ीत ि ेत्र वा बाटो बािेक अन्य ि ेत्र वा बाटोबाट पद यात्रा गर ाएमा कान ून को उल्लङ्घन गरेको\nमानन न ेछ ।","children":[{"tier":3,"nodeType":"clause"